import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.e4u2V5E7.js";const g=JSON.parse('{"title":"Bug Investigation Playbook","description":"Engineering playbook for bug investigation workflow","frontmatter":{"title":"Bug Investigation Playbook","description":"Engineering playbook for bug investigation workflow"},"headers":[],"relativePath":"playbooks/bug-investigation.md","filePath":"playbooks/bug-investigation.md","lastUpdated":1784485118000}'),n={name:"playbooks/bug-investigation.md"};function r(o,e,l,d,c,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="bug-investigation-playbook" tabindex="-1">Bug Investigation Playbook <a class="header-anchor" href="#bug-investigation-playbook" aria-label="Permalink to &quot;Bug Investigation Playbook&quot;">​</a></h1><h1 id="playbook-bug-investigation" tabindex="-1">Playbook: Bug Investigation <a class="header-anchor" href="#playbook-bug-investigation" aria-label="Permalink to &quot;Playbook: Bug Investigation&quot;">​</a></h1><p><strong>Goal:</strong> Systematically identify, diagnose, and resolve bugs with root cause analysis.</p><p><strong>Trigger:</strong> User reports a bug, error, or unexpected behavior.</p><p><strong>Inputs:</strong></p><ul><li>Bug description or error message</li><li>Steps to reproduce (if known)</li><li>Affected area (frontend, backend, database, API)</li><li>Environment (development, staging, production)</li></ul><p><strong>Outputs:</strong></p><ul><li>Root cause analysis</li><li>Fix implementation</li><li>Prevention recommendation</li><li>Updated test coverage (if applicable)</li></ul><p>----|------| | <code>build</code> | Primary investigator, code search, fix implementation | | <code>frontend</code> | UI-related bugs, rendering issues, client-side logic | | <code>backend</code> | API bugs, server logic, data processing | | <code>database</code> | Query issues, schema problems, migration bugs | | <code>security</code> | Security-related bugs, auth issues | | <code>reviewer</code> | Verify fix doesn&#39;t introduce regressions |</p><h2 id="required-skills" tabindex="-1">Required Skills <a class="header-anchor" href="#required-skills" aria-label="Permalink to &quot;Required Skills&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Skill</th><th>When to Load</th></tr></thead><tbody><tr><td><code>debugging-workflow</code></td><td>Always — systematic debugging methodology</td></tr><tr><td><code>react-patterns</code></td><td>Frontend bugs involving React</td></tr><tr><td><code>nextjs-app-router</code></td><td>Next.js routing or rendering bugs</td></tr><tr><td><code>supabase-patterns</code></td><td>Database query bugs</td></tr><tr><td><code>api-design</code></td><td>API endpoint bugs</td></tr><tr><td><code>error-handling</code></td><td>Error boundary or catch block issues</td></tr></tbody></table><h2 id="required-commands" tabindex="-1">Required Commands <a class="header-anchor" href="#required-commands" aria-label="Permalink to &quot;Required Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>When to Use</th></tr></thead><tbody><tr><td><code>/review</code></td><td>After fix — verify no regressions</td></tr><tr><td><code>/security-scan</code></td><td>If bug involves auth or data access</td></tr></tbody></table><hr><h2 id="process" tabindex="-1">Process <a class="header-anchor" href="#process" aria-label="Permalink to &quot;Process&quot;">​</a></h2><h3 id="step-1-reproduce-5-min" tabindex="-1">Step 1: Reproduce (5 min) <a class="header-anchor" href="#step-1-reproduce-5-min" aria-label="Permalink to &quot;Step 1: Reproduce (5 min)&quot;">​</a></h3><ol><li>Clarify the exact steps to reproduce</li><li>Identify the environment</li><li>Confirm the bug is reproducible</li><li>Capture the exact error message or behavior</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ask the user:</span></span>
<span class="line"><span>- What did you expect to happen?</span></span>
<span class="line"><span>- What actually happened?</span></span>
<span class="line"><span>- Can you provide the exact error message?</span></span>
<span class="line"><span>- What browser/device/environment?</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="step-2-isolate-10-min" tabindex="-1">Step 2: Isolate (10 min) <a class="header-anchor" href="#step-2-isolate-10-min" aria-label="Permalink to &quot;Step 2: Isolate (10 min)&quot;">​</a></h3><ol><li><strong>Narrow the scope</strong> — Frontend? Backend? Database? Network?</li><li><strong>Check recent changes</strong> — <code>git log --oneline -10</code> for recent commits</li><li><strong>Search for error</strong> — Grep for error message in codebase</li><li><strong>Check logs</strong> — Server logs, browser console, network tab</li><li><strong>Map the flow</strong> — Trace the request from trigger to result</li></ol><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Useful commands</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -10</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Recent changes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HEAD~1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # Last commit changes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blame</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # Who wrote this code</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="step-3-diagnose-15-min" tabindex="-1">Step 3: Diagnose (15 min) <a class="header-anchor" href="#step-3-diagnose-15-min" aria-label="Permalink to &quot;Step 3: Diagnose (15 min)&quot;">​</a></h3><ol><li><strong>Form hypotheses</strong> — What could cause this behavior?</li><li><strong>Test hypotheses</strong> — Add console.log, check data, verify assumptions</li><li><strong>Identify root cause</strong> — Not just the symptom, but the underlying issue</li><li><strong>Document findings</strong> — Write down what you found</li></ol><p>Common root causes:</p><ul><li><strong>Null/undefined</strong> — Missing data, async timing, optional chaining</li><li><strong>State mutation</strong> — Direct state modification in React</li><li><strong>Race condition</strong> — Async operations completing out of order</li><li><strong>Stale closure</strong> — Variable captured by closure is outdated</li><li><strong>Missing validation</strong> — Input not validated at boundary</li><li><strong>Incorrect query</strong> — Wrong filter, missing join, N+1 query</li><li><strong>Cache issue</strong> — Stale cache, missing invalidation</li><li><strong>Environment mismatch</strong> — Dev vs prod configuration difference</li></ul><h3 id="step-4-fix-15-min" tabindex="-1">Step 4: Fix (15 min) <a class="header-anchor" href="#step-4-fix-15-min" aria-label="Permalink to &quot;Step 4: Fix (15 min)&quot;">​</a></h3><ol><li><strong>Implement the fix</strong> — Address root cause, not just symptom</li><li><strong>Check for similar issues</strong> — Same pattern elsewhere?</li><li><strong>Add defensive code</strong> — Prevent recurrence</li><li><strong>Update types</strong> — If bug was type-related</li><li><strong>Add error handling</strong> — If bug was unhandled case</li></ol><h3 id="step-5-verify-10-min" tabindex="-1">Step 5: Verify (10 min) <a class="header-anchor" href="#step-5-verify-10-min" aria-label="Permalink to &quot;Step 5: Verify (10 min)&quot;">​</a></h3><ol><li><strong>Test the fix</strong> — Confirm bug is resolved</li><li><strong>Test related functionality</strong> — No regressions</li><li><strong>Build check</strong> — <code>npm run build</code> passes</li><li><strong>Run <code>/review</code></strong> — Get a quality review</li></ol><h3 id="step-6-prevent-5-min" tabindex="-1">Step 6: Prevent (5 min) <a class="header-anchor" href="#step-6-prevent-5-min" aria-label="Permalink to &quot;Step 6: Prevent (5 min)&quot;">​</a></h3><ol><li><strong>Add test case</strong> — Prevent regression</li><li><strong>Update documentation</strong> — If this was a common pitfall</li><li><strong>Consider linting rule</strong> — If applicable</li><li><strong>Document in project AGENTS.md</strong> — If this reveals a pattern</li></ol><hr><h2 id="validation-steps" tabindex="-1">Validation Steps <a class="header-anchor" href="#validation-steps" aria-label="Permalink to &quot;Validation Steps&quot;">​</a></h2><ul><li>[ ] Bug is reproducible before fix</li><li>[ ] Root cause is identified (not just symptom)</li><li>[ ] Fix addresses root cause</li><li>[ ] Fix doesn&#39;t break other functionality</li><li>[ ] Build passes after fix</li><li>[ ] Related code paths are checked for similar issues</li><li>[ ] Error handling is improved (if applicable)</li></ul><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>Bug is resolved</li><li>Root cause is documented</li><li>No regressions introduced</li><li>Prevention measures are in place</li><li>Code quality is maintained or improved</li></ul><h2 id="common-pitfalls" tabindex="-1">Common Pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common Pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>Why It&#39;s Wrong</th><th>Correct Approach</th></tr></thead><tbody><tr><td>Fixing the symptom</td><td>Bug recurs in different scenario</td><td>Find and fix root cause</td></tr><tr><td>Over-engineering the fix</td><td>Adds unnecessary complexity</td><td>Minimal, targeted fix</td></tr><tr><td>Not checking similar code</td><td>Same bug exists elsewhere</td><td>Search for similar patterns</td></tr><tr><td>Skipping build check</td><td>Fix introduces compile errors</td><td>Always run <code>npm run build</code></td></tr><tr><td>Not testing edge cases</td><td>Bug recurs with different input</td><td>Test boundary conditions</td></tr><tr><td>Rushing to fix without understanding</td><td>Wrong fix or missed root cause</td><td>Take time to diagnose first</td></tr><tr><td>Adding try/catch everywhere</td><td>Swallows errors silently</td><td>Handle errors at proper boundaries</td></tr></tbody></table><h2 id="related-commands" tabindex="-1">Related Commands <a class="header-anchor" href="#related-commands" aria-label="Permalink to &quot;Related Commands&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/commands/">Commands Registry</a> for commands used in this playbook.</p><h2 id="related-agents" tabindex="-1">Related Agents <a class="header-anchor" href="#related-agents" aria-label="Permalink to &quot;Related Agents&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/agents/">Agents Registry</a> for agents involved in this playbook.</p>`,42)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
